import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';

/**
 * Validate that issueDate is in YYYY-MM-DD format and represents a real date.
 * @param {string} issueDate
 * @returns {boolean}
 */
function isValidDate(issueDate) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(issueDate)) return false;
  const date = new Date(issueDate + 'T00:00:00Z');
  return date instanceof Date && !isNaN(date) && date.toISOString().slice(0, 10) === issueDate;
}

/**
 * Validate that discountPercent is a valid number from 0 to 100.
 * @param {unknown} discountPercent
 * @returns {boolean}
 */
function isValidDiscount(discountPercent) {
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Create an invoice with the given customer, issue date, and lines.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  const invoiceLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    const discountPercent =
      'discountPercent' in line ? line.discountPercent : TIER_DISCOUNTS[customerResult.value.tier];
    if (!isValidDiscount(discountPercent)) return fail('DISCOUNT_INVALID');

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId,
    customerName: customerResult.value.name,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

/**
 * Calculate the total amount of a single line item (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount amount of a single line item.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  const total = lineTotal(line);
  const discountPercent = line.discountPercent ?? 0;
  return roundCents(total * discountPercent / 100);
}

/**
 * Calculate the VAT amount of a single line item.
 * VAT is calculated on the line amount after discount.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
 * @returns {number}
 */
export function lineVat(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const amountAfterDiscount = total - discount;
  return roundCents(amountAfterDiscount * line.vatRate / 100);
}

/**
 * Calculate subtotal, discount, VAT, and total for an invoice.
 * VAT is calculated per line on the amount after discount, then summed.
 * Total is clamped at 0 (never negative).
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
  const total = Math.max(0, subtotal - discount + vat);
  return { subtotal, discount, vat, total };
}

/**
 * Add or increase a line on a draft invoice.
 * @param {{ status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} param1
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  const discount = discountPercent ?? 0;
  if (!isValidDiscount(discount)) return fail('DISCOUNT_INVALID');

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;

  const existingLineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  let newLines;
  if (existingLineIndex >= 0) {
    newLines = invoice.lines.map((line, i) =>
      i === existingLineIndex ? { ...line, qty: line.qty + qty } : line
    );
  } else {
    newLines = [
      ...invoice.lines,
      {
        sku,
        name: product.name,
        qty,
        unitPrice: product.unitPrice,
        vatRate: product.vatRate,
        discountPercent: discount,
      },
    ];
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineExists = invoice.lines.some((line) => line.sku === sku);
  if (!lineExists) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice with a generated invoice number.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {string[]} existingNumbers
 * @returns {{ ok: true, value: { status: string, number: string } } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

