test('invoiceTotals from actual createInvoice result', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 42500 + 95000);
  assert.equal(totals.discount, 6875);
  const afterDiscount = 137500 - 6875;
  const expectedVat = Math.round(afterDiscount * 21 / 100);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, afterDiscount + expectedVat);
});

